import math
def interp(points,u):
    if not points:return None
    pts=sorted(points,key=lambda p:p[0])
    if u<=pts[0][0]:return pts[0][1]
    if u>=pts[-1][0]:return pts[-1][1]
    for (a,x),(b,y) in zip(pts,pts[1:]):
        if a<=u<=b:return x+(y-x)*(u-a)/(b-a)
def control(obs):
    lm=obs.get('local_map',{});L=lm.get('left_rail',[]);R=lm.get('right_rail',[])
    centers=[]
    for u,v in L:
        rv=interp(R,u)
        if rv is not None:centers.append((u,(v+rv)/2))
    target=interp(centers,4.0) if centers else 0.0
    bearing=math.degrees(math.atan2(target or 0,4.0))
    h=float(obs.get('hitch_deg',0))
    steer=max(-20,min(20,-0.65*bearing+0.9*h))
    speed=-0.48 if abs(h)>18 or abs(bearing)>10 else -0.65
    return (steer,speed,180)

