    y=interp(centers,2.5)
    bearing=math.degrees(math.atan2(y or 0,2.5))
    # While reversing, steer opposite the desired rear-trailer path; correct hitch swing toward zero.
    steer=max(-12,min(12,-0.45*bearing+0.7*h))
    speed=-0.28 if abs(bearing)>14 else -0.38
