import math
def control(obs):
    h=float(obs.get('hitch_deg',0.0))
    lm=obs.get('local_map',{}) or {}
    L=lm.get('left_rail',[]) or []
    R=lm.get('right_rail',[]) or []
    def interp(points,u):
        pts=sorted((float(p[0]),float(p[1])) for p in points)
        if not pts: return None
        if u<=pts[0][0]: return pts[0][1]
        for (a,x),(b,y) in zip(pts,pts[1:]):
            if a<=u<=b:
                q=(u-a)/(b-a) if b!=a else 0.0
                return x+q*(y-x)
        return pts[-1][1]
    bearings=[]
    for look in (3.0,5.0,7.0):
        vl,vr=interp(L,look),interp(R,look)
        if vl is not None and vr is not None:
            bearings.append(math.degrees(math.atan2((vl+vr)/2.0,look)))
    route=float(obs.get('route',{}).get('bearing_deg',0.0))
    desired=max(-22.0,min(22.0,sum(bearings)/len(bearings) if bearings else route))
    steer=max(-32.0,min(32.0,1.45*(h-desired)))
    speed=-0.75 if abs(desired)<8 and abs(h-desired)<10 else -0.48
    if abs(h)>35: speed=-0.32
    return (steer,speed,180)

