import math
def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    if abs(h) > 14.0:
        return (0.0, 0.35, 0.0)
    mp = obs.get('local_map', {})
    left, right = mp.get('left_rail', []), mp.get('right_rail', [])
    pairs = []
    for a in left:
        u, vl = float(a[0]), float(a[1])
        if 1.2 <= u <= 4.0:
            b = min(right, key=lambda q: abs(float(q[0])-u), default=None)
            if b is not None and abs(float(b[0])-u) < 0.22:
                pairs.append((u, (vl + float(b[1])) * 0.5))
    if pairs:
        u, center_v = min(pairs, key=lambda x: abs(x[0]-2.5))
        path = math.degrees(math.atan2(center_v, max(1.0, u)))
    else:
        path = 0.0
    steer = max(-18.0, min(18.0, 0.55*h + 0.35*path))
    return (steer, -0.20, 180.0)

